WITH filtered AS (SELECT id, device, browser, started_at, country, CONCAT(country, '/', device) AS country_device FROM sessions WHERE started_at >= TO_TIMESTAMP('2023-09-12 16:00:00') AND country IS NOT NULL), latest_match AS (SELECT s.id, s.started_at, x.web_event_event_time, x.web_event_event_type FROM filtered s JOIN LATERAL (SELECT c.event_time AS web_event_event_time, c.event_type AS web_event_event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) x ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_time >= s.started_at)), latest AS (SELECT * FROM not_flagged QUALIFY ROW_NUMBER() OVER (PARTITION BY web_event_event_type ORDER BY started_at NULLS LAST, id) = 1) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, COUNT(*) FILTER (WHERE web_event_event_type = 'page_view') AS page_view_rows, SORT_ARRAY(COLLECT_SET(web_event_event_type)) AS web_event_event_type_list, SIZE(COLLECT_SET(web_event_event_type)) AS num_web_event_event_types FROM latest GROUP BY DATE_TRUNC('YEAR', started_at) ORDER BY page_view_rows DESC
